# Conditional routes: U901.16 (CR_RTERM) and U901.25 (CR_3V3, the 3.3 V LDO output) are boxed in by f_fanout's GND
# dog-bone vias of C906.2 (134.3, 121.72) and C910.2 (128.7, 120.3). These entries were computed as if those two pads
# used a 0.351/0.15 via-in-pad instead; each one is drawn only when no GND via sits at its blocking point any more.
COND = [
    ('cond_rterm_via', 'CR_RTERM', 0.15, [], [(134.3, 121.64)], (0.35, 0.15), [(134.3, 121.72)]),
    ('cond_rterm_stub', 'CR_RTERM', 0.15, [('B', [(134.3, 121.225), (134.3, 121.65)])], [], (0.45, 0.25), [(134.3, 121.72)]),
    ('cond_rterm', 'CR_RTERM', 0.15, [('F', [(134.3, 121.64), (134.875, 122.215), (134.875, 124.59), (133.0, 126.465)]), ('B', [(133.0, 126.465), (133.0, 126.165)])], [(133.0, 126.465)], (0.45, 0.25), [(134.3, 121.72)]),
    ('cond_3v3_25_via', 'CR_3V3', 0.15, [], [(128.8, 120.3)], (0.35, 0.15), [(128.7, 120.3)]),
    ('cond_3v3_25_stub', 'CR_3V3', 0.2, [('B', [(129.225, 120.275), (129.2, 120.3), (128.8, 120.3)])], [], (0.45, 0.25), [(128.7, 120.3)]),
    ('cond_3v3_25', 'CR_3V3', 0.2, [('L3', [(128.8, 120.3), (128.8, 121.5)]), ('B', [(128.8, 121.5), (128.8, 122.175)])], [(128.8, 121.5)], (0.45, 0.25), [(128.7, 120.3)]),
]

LAYER = {"F": "F.Cu", "L3": "In2.Cu", "B": "B.Cu"}


def _blocked(board, pts):
    import pcbnew
    for t in board.GetTracks():
        if t.GetClass() == "PCB_VIA" and t.GetNetname() == "GND":
            p = t.GetPosition()
            if any(abs(pcbnew.ToMM(p.x) - x) < 0.05 and abs(pcbnew.ToMM(p.y) - y) < 0.05 for x, y in pts):
                return True
    return False


def route(board, r):
    for name, net, w, segs, vias, (vd, vdrill) in ROUTES:
        for layer, pts in segs:
            r.track(net, pts, LAYER[layer], w)
        for x, y in vias:
            r.via(net, x, y, vd, vdrill)
    skipped = []
    for name, net, w, segs, vias, (vd, vdrill), block in COND:
        if _blocked(board, block):
            skipped.append(name)
            continue
        for layer, pts in segs:
            r.track(net, pts, LAYER[layer], w)
        for x, y in vias:
            r.via(net, x, y, vd, vdrill)
    if skipped:
        print("g_front: U901.16 / U901.25 still boxed in by f_fanout GND vias (C906.2 / C910.2) -> skipped", skipped)
